    'rm.a': 'Tailscale - شبكة خاصة لأجهزتك',
    'rm.a.b': 'مجانية للمركز، ولا تحتاج شراء شيء. ثبّت Tailscale على جهاز المركز وعلى كل هاتف أو حاسوب سيعمل من الخارج، وادخل بالحساب نفسه، وفعّل «Tailscale serve» لعنوان «حصة». لا يرى العنوان إلا أجهزتك. وتسمح الشبكة الخاصة نفسها لحاسوب في المنزل بأن يحتفظ بنسخته ويزامنها مع المركز (الأجهزة والمزامنة).',
