    'rm.pcOff': 'إذا كان جهاز المركز مغلقًا أو بلا إنترنت فلا يستطيع أحد العمل من الخارج: تعرض الصفحات المفتوحة «انقطع الاتصال بجهاز المركز» ولا تحفظ شيئًا. أما الحاسوب الذي يحتفظ بنسخته (الأجهزة والمزامنة) فيستمر في العمل ويلحق لاحقًا.',
