    'hq.door.9.q': 'كيف أبيع ملزمة أو أشحن رصيدًا مقدمًا عند الاستقبال؟',
    'hq.door.9.a': 'افتح بطاقة الطالب واضغط «بيع ملزمة» أو «شحن رصيد مقدم». الطالب محدد مسبقًا، وملازم معلميه تظهر أولًا، ولا يمكن بيع أكثر من المخزون.',
    'hq.door.10.q': 'ظهر شريط أحمر يقول إن الاتصال بجهاز المركز انقطع.',
    'hq.door.10.a': 'لا يمكن حفظ شيء حتى يعود الاتصال، ولا يدّعي البرنامج حفظ شيء لم يُحفظ. عند عودته تابع العمل. وإذا ضغطت «حفظ» في دفع ولم يصل رد فاضغطه مرة أخرى: لا يُحصَّل المبلغ مرتين أبدًا.',
