    'hq.printing.1.a': 'الإعدادات ← المظهر ← الطباعة على هذا الجهاز: اختر لفة 58 مم أو 80 مم أو ورقة A5، واضغط «طباعة تجريبية». يحتفظ كل جهاز باختياره.',
    'hq.printing.2.q': 'هل أطبع كل إيصال تلقائيًا؟',
    'hq.printing.2.a': 'من المكان نفسه: «اطبع كل إيصال فورًا». وإلا اضغط «طباعة» في سطر الإيصال في بطاقة الطالب. إعادة الطباعة لا تُنشئ إيصالًا جديدًا أبدًا.',
    'hq.printing.3.q': 'ماذا يمكنني أن أطبع أيضًا؟',
    'hq.printing.3.a': 'بطاقات الطلاب (10 في ورقة A4)، وكشف الحضور الورقي للمجموعة، ونتائج الامتحان، وتقرير الوردية، وكشوف المعلمين، وتقرير الشهر، وكشف مجموعة التقوية بالمدرسة.',
    'hq.safety': 'أمان البيانات',
    'hq.safety.1.q': 'هل يمكن أن تضيع البيانات؟',
    'hq.safety.1.a': 'لا يُحذف شيء نهائيًا: السجلات المحذوفة تذهب إلى سلة المحذوفات، والحسابات لا تُصحَّح إلا بقيود عكسية، والنسخ الاحتياطي يُؤخذ تلقائيًا.',
    'hq.safety.2.q': 'تعمل عدة أجهزة في الوقت نفسه، فهل تتفق؟',
    'hq.safety.2.a': 'نعم. يحتفظ كل جهاز بنسخة كاملة ويعمل وحده عند انقطاع الشبكة، وعند عودتها تتبادل الأجهزة التغييرات فتنتهي جميعها بالبيانات نفسها.',
    'hq.safety.3.q': 'من غيّر ماذا؟',
    'hq.safety.3.a': 'يُحفظ كل تغيير باسم صاحبه ووقته وجهازه في سجل النشاط.',
    'hq.safety.4.q': 'ماذا يستطيع كل شخص أن يفعل؟',
    'hq.safety.4.a': 'يحدد المسؤول صلاحيات كل حساب، ويستطيع قصر حساب المعلم على مجموعاته. والخادم يتحقق من كل عملية، لا الشاشة وحدها.',
    'hq.safety.5.q': 'غيّرت شيئًا بالخطأ. هل أستطيع التراجع؟',
    'hq.safety.5.a': 'نعم. افتح ملف الطالب واضغط «السجل» ثم «التراجع عن هذا التغيير» أمام السجل المطلوب. تعود القيم السابقة كتغيير جديد فيحتفظ السجل بكل شيء. أما السجل المحذوف فتجده في سلة المحذوفات.',
    'hq.safety.6.q': 'أين تذهب النسخ الاحتياطية، وكيف أطمئن على بياناتي؟',
    'hq.safety.6.a': 'الإعدادات ← البيانات والنسخ. تُنشأ النسخ تلقائيًا؛ اختر فلاشة (USB) هناك لتكون النسخة الثانية على قرص آخر. اضغط «افحص بياناتي الآن» لفحص كل السجلات. وتعرض النظرة العامة آخر نسخة في «هل كل شيء آمن؟».',
    'hq.devices': 'عدة أجهزة والمشاركة',
    'hq.devices.1.q': 'ماذا يعني الضوء في الأعلى؟',
    'hq.devices.1.a': 'أخضر: كل الأجهزة محدّثة. أزرق: المشاركة جارية الآن. برتقالي: هذا الجهاز يعمل منفردًا (الجهاز الآخر مغلق أو الشبكة مقطوعة)، لا يضيع شيء ويلحق بالباقي تلقائيًا. أحمر: افتح «الأجهزة والمزامنة» واقرأ التحذير.',
    'hq.devices.2.q': 'كيف أضيف لابتوب الاستقبال؟',
    'hq.devices.2.a': 'على جهاز المركز اضغط «إضافة جهاز». وعلى اللابتوب افتح حصة واختر «الانضمام إلى جهاز المركز» ثم اختر العنوان الظاهر أو اكتبه. تبقى النافذة مفتوحة 15 دقيقة وتُغلق بعد انضمام جهاز واحد.',
    'hq.devices.3.q': 'جهازان غيّرا الشيء نفسه. ماذا أفعل؟',
    'hq.devices.3.a': 'افتح «الأجهزة والمزامنة» ← بانتظار قرارك. تظهر كل قيمة مع من غيّرها ومتى؛ اضغط «اعتمد هذه» أمام الصحيحة. لا يضيع شيء وتعرض كل الأجهزة قرارك.',
    'hq.devices.4.q': 'ما هو مفتاح المسؤول ولماذا أحفظه؟',
    'hq.devices.4.a': 'هو الذي يثبت أن جهاز المركز هو الأصلي. إذا تعطل جهاز المركز فالمفتاح هو الوسيلة الوحيدة لمواصلة إدارة الحسابات والأجهزة من جهاز آخر. احفظه مرة واحدة على فلاشة وضعها في مكان آمن.',
    'hq.devices.5.q': 'ضاع لابتوب أو سُرق. ماذا أفعل؟',
    'hq.devices.5.a': 'افتح «الأجهزة والمزامنة» واضغط «إزالة» على ذلك الجهاز. لن يستطيع بعدها إرسال البيانات أو استقبالها، ويبقى كل ما سجّله في السجل. بعدها غيّر كلمات مرور من استخدموه.',
    'hq.devices.6.q': 'هل يجب أن ينضم كل جهاز؟',
    'hq.devices.6.a': 'لا. الجهاز الذي ينضم يحتفظ بنسخته ويعمل حتى لو أُغلق جهاز المركز. أما الجهاز الذي يريد الاطلاع فقط فيفتح عنوان جهاز المركز في المتصفح ويسجّل الدخول.',
