    'gd.sample.4': 'افتح صفحة الطلاب: 420 طالبًا بصفوفهم ومجموعاتهم وأرصدتهم. النقطة الحمراء تعني «يحتاج متابعة»، والرصيد بالسالب يعني أن على الطالب مبلغًا مستحقًا.',
