    'gd.sample.6': 'حسابات العينة (desk1 وt.ahmed وغيرها) تأخذ كلمة مرور جديدة في كل مرة تُحمَّل فيها العينة، ويعرضها زر «كلمة مرور العينة» للمديرين فقط. لا تعطها لموظفين حقيقيين؛ وسجلاتك الحقيقية لا تتأثر.',
    'gd.sample.7': 'عندما تكون جاهزًا للعمل الحقيقي: الإعدادات ← [[set.tab.data]] ← [[sample.delete]] ثم أكّد.',
    'gd.sample.8': 'تُزال كل طلاب العينة ومجموعاتها وإيصالاتها وحساباتها (تُنقل إلى سلة المحذوفات، فحتى هذا يمكن التراجع عنه). وتبقى السجلات التي أدخلتها بنفسك.',
