    'wa.lv.critical.b': 'أنماط تعني عادةً أن مالًا اختفى.',
    'wa.lv.high.b': 'أخطاء أو قرارات تغيّر المال؛ اسأل الشخص.',
    'wa.lv.warn.b': 'غير معتاد وغالبًا بريء؛ ألقِ نظرة وامضِ.',
    'wa.lv.info.b': 'تغييرات المديرين أنفسهم، محفوظة للعلم.',
    'wa.people': 'من تتحدث معه',
    'wa.people.b': 'التنبيهات المفتوحة لكل شخص في هذه الفترة.',
