    'wa.review': 'تمت المراجعة',
    'wa.reviewShown': 'اعتبار كل المعروض مُراجَعًا ({n})',
    'wa.review.t': 'تمت المراجعة؛ ماذا وجدت؟',
    'wa.review.b': 'اكتب سطرًا للسجل (مثل «سألت سارة: الطابعة علقت وأُعيد الإيصال»). يُحفظ اسمك والوقت معه، وينتقل التنبيه إلى «تمت مراجعته».',
