    'wa.none': 'لا شيء يحتاج إلى عينك',
    'wa.none.b': 'لا قيود عكسية ولا فروق درج ولا حضور بلا دفع ولا تعديلات خطرة في هذه الفترة.',
    'wa.noMatch': 'لا يوجد تنبيه يطابق هذه التصفية.',
    'wa.export': 'تصدير',
    'wa.rules': 'الحدود: ساعات العمل {a}-{b}، المبلغ الكبير {big}، عدم الدفع بعد {u} وحدات. غيّرها من الإعدادات ← القواعد.',
    'wa.card.t': 'الرقابة',
    'wa.card.b': '{c} خطير، و{h} للمراجعة اليوم.',
    'wa.card.clean': 'لا شيء مريب في آخر 7 أيام.',
    'wa.card.go': 'افتح الرقابة',
    'wa.rn.void': 'إيصالات بقيد عكسي',
    'wa.r.void': 'أُلغي الإيصال {no} ({amount}) لـ{name} بقيد عكسي. السبب: «{reason}».',
    'wa.void.same': 'الشخص نفسه حصّله ثم ألغاه.',
    'wa.void.days': 'أُلغي بعد {n} يوم من تحصيله.',
    'wa.void.closed': 'كان درجه قد عُدّ وأُغلق بالفعل.',
    'wa.r.void.why': 'القيد العكسي يُخرج المال من الدفاتر. أغلبه أخطاء كتابة بريئة، لكن الإلغاء بعد أيام، أو بعد إغلاق الدرج، أو من نفس الشخص الذي حصّل المال، هو الطريق المعتاد لاختفاء النقدية.',
    'wa.r.void.do': 'يُلغى الإيصال في اليوم نفسه فقط وبسبب حقيقي، ثم يُحصَّل المبلغ الصحيح فورًا. اطلب من ولي الأمر الإيصال الورقي؛ إن كان معه فالمبلغ دُفع.',
    'wa.rn.skim': 'إلغاء ثم تحصيل أقل',
    'wa.r.skim': '{name}: أُلغي الإيصال {no} بمبلغ {amount} وحُصّل {no2} بمبلغ {amount2} في اليوم نفسه؛ أي أقل بـ{diff}.',
    'wa.r.skim.why': 'وليّ الأمر دفع المبلغ كاملًا ومعه الإيصال الورقي الأول، بينما يبقى في الدفاتر المبلغ الأصغر فقط؛ والفرق غالبًا في جيب أحد.',
    'wa.r.skim.do': 'اتصل بوليّ الأمر واسأله كم دفع وما رقم الإيصال الذي معه. التصحيح لا يحتاج أبدًا إلى إيصال ثانٍ أصغر: يُلغى بسبب ويُحصَّل ما دُفع بالضبط.',
    'wa.rn.short': 'عجز في الدرج',
    'wa.r.short': 'أُغلق الدرج {no} بعجز {diff} (المفروض {expected}، والمعدود {counted}). السبب المكتوب: «{reason}».',
    'wa.r.short.why': 'مال استُلم وليس في الدرج.',
    'wa.r.short.do': 'عُدّ مع الشخص صباح اليوم التالي، وراجع المصروفات غير المسجلة والدفعات المكتوبة فودافون كاش وهي نقدية. الفروق الصغيرة تحدث، أما المتكررة فلا.',
    'wa.rn.over': 'زيادة في الدرج',
    'wa.r.over': 'أُغلق الدرج {no} بزيادة {diff} (المفروض {expected}، والمعدود {counted}). السبب: «{reason}».',
    'wa.r.over.why': 'الزيادة تعني غالبًا أن مبلغًا حُصّل بلا إيصال؛ فوليّ الأمر لم يأخذ إيصالًا والطالب ما زال يبدو غير مسدد.',
    'wa.r.over.do': 'كل جنيه يأخذ إيصالًا لحظة استلامه. اعرف لمن هذا المال (من دفع اليوم وليس معه إيصال) وسجّله.',
    'wa.rn.repeatShort': 'عجز متكرر',
    'wa.r.repeatShort': '{n} مرات إغلاق بعجز في هذه الفترة، بإجمالي {total}.',
    'wa.r.repeatShort.why': 'العجز مرة خطأ، أما التكرار فليس كذلك.',
    'wa.r.repeatShort.do': 'تحدث مع الشخص، وعُدّا معًا في بداية ونهاية الورديات القادمة، وفكّر في سحب صلاحية [[perm.money.void]] حتى يتوقف.',
    'wa.rn.openShift': 'وردية لم تُغلق',
