    'gd.watch.9': 'أخبر الموظفين بوجود الرقابة؛ فأغلب السرقة تتوقف عندما يعرف الناس أن كل ضغطة محفوظة.',
    'gd.watch.ok': 'تصبح البطاقات صفرًا أو يظهر على كل تنبيه من راجعه.',
    'gd.watch.x': 'إعطاء الموظفين صلاحيات المدير البرتقالية؛ فيستطيعون حينها مراجعة تنبيهاتهم بأنفسهم. احتفظ بها لنفسك.',
    'sit.theft.q': 'أشك أن أحدًا في الاستقبال يأخذ مالًا',
    'sit.theft.a': 'لا تتهم، بل راقب. تُظهر صفحة الرقابة القيود العكسية التي يتبعها تحصيل أقل، والأدراج المغلقة بعجز متكرر، والطلاب الذين يحضرون دون دفع. افتح سجل النشاط ← [[act.tab.clicks]] لليوم نفسه لترى ما ضُغط ومتى. ثم اتصل بوليّين أو ثلاثة واسألهم كم دفعوا وما رقم الإيصال الذي معهم. الإيصال الورقي برقم غير موجود في البرنامج دليل.',
    'sit.cashNoReceipt.q': 'وليّ أمر يقول إنه دفع ولم يأخذ إيصالًا',
    'sit.cashNoReceipt.a': 'المال المأخوذ بلا إيصال هو الأصعب في الاكتشاف، فاجعلها قاعدة يعرفها الجميع: «لا إيصال = لم يُدفع». ضع لافتة على المكتب. وراجع في الرقابة الأدراج المغلقة بزيادة (مال بلا إيصال) والطلاب الذين يحضرون دون دفع. الإيصالات مرقّمة بالترتيب على كل جهاز، ولا يمكن إخفاء رقم مفقود.',
    'sit.staffAccount.q': 'الموظفون يستخدمون كلمة مرور واحدة',
